class ExpressionEvaluator:
    def __init__(self):
        self.pos = 0
        self.tokens = []

    def tokenize(self, expr):
        tokens = []
        i = 0
        while i < len(expr):
            if expr[i].isspace():
                i += 1
                continue
            elif expr[i].isdigit():
                j = i
                while j < len(expr) and expr[j].isdigit():
                    j += 1
                tokens.append((int(expr[i:j]), 'NUM'))
                i = j
            elif expr[i] == '-':
                # Check if it's a unary minus (at start or after operator/paren close)
                if not tokens:
                    tokens.append((-0), 'UNARY_MINUS')  # Placeholder, handle logic below
                else:
                    prev_op = tokens[-1][1] if tokens else None
                    if prev_op in ('NUM', ')', '('):
                        j = i + 1
                        while j < len(expr) and expr[j].isdigit():
                            j += 1
                        tokens.append((int('-' + expr[i:j]), 'NUM'))
                        i = j
                        continue
                tokens.append(('-', 'OPERATOR'))
                i += 1
            elif expr[i] == '+':
                tokens.append(('+', 'OPERATOR'))
                i += 1
            elif expr[i] == '*':
                tokens.append(('*', 'OPERATOR'))
                i += 1
            elif expr[i] == '/':
                tokens.append(('/', 'OPERATOR'))
                i += 1
            elif expr[i] == '(':
                tokens.append(('(', 'PAREN'))
                i += 1
            elif expr[i] == ')':
                tokens.append((')', 'PAREN'))
                i += 1
            else:
                raise ValueError(f"Invalid character '{expr[i]}' at position {i}")

    def reset(self):
        self.pos = 0
        self.tokens = []

    def parse(self, expr):
        if not expr or not expr.strip():
            return None
        try:
            token_list = list(expr)  # Re-tokenize manually for accuracy
            self.tokenizer(expr).tokenize()
            tokens = self.tokenizer(expr).tokens
            result = self.parse_primary(tokens)
            return result
        except Exception as e:
            if isinstance(e, ZeroDivisionError):
                raise
            else:
                raise ValueError(f"Invalid expression: {expr}") from e

    def tokenizer(self, expr):
        tokens = []
        i = 0
        n = len(expr)
        while i < n:
            ch = expr[i]
            if ch.isdigit():
                j = i + 1
                while j < n and expr[j].isdigit():
