                num = int(expr[i:j])
                tokens.append((num, 'NUM'))
                i = j
            elif ch == '+':
                tokens.append(('-', 'NEGATOR') if (not tokens or tokens[-1][1] in ('NUM', ')')) else ('+', 'OPERATOR'))
                i += 1
            elif ch == '-':
                if not tokens:
                    # Unary minus at start
                    j = i + 1
                    while j < n and expr[j].isdigit():
                        j += 1
                    num = int('-' + expr[i:j])
                    tokens.append((num, 'NUM'))
                    i = j
                else:
                    prev_op = tokens[-1][1]
                    if prev_op in ('NUM', ')'):
                        # Unary minus
                        j = i + 1
                        while j < n and expr[j].isdigit():
                            j += 1
                        num = int('-' + expr[i:j])
                        tokens.append((num, 'NUM'))
                        i = j
                    else:
                        tokens.append(('-', 'OPERATOR'))
                        i += 1
            elif ch == '*':
                tokens.append(('*', 'OPERATOR'))
                i += 1
            elif ch == '/':
                tokens.append(('/', 'OPERATOR'))
                i += 1
            elif ch == '(':
                tokens.append(('(', 'OPEN_PAREN'))
                i += 1
            elif ch == ')':
                tokens.append((')', 'CLOSE_PAREN'))
                i += 1
            else:
                raise ValueError(f"Invalid character '{ch}'")
        return self

    def parse_primary(self, tokens):
        if not self.tokens or len(self.tokens) == self.pos:
            raise ValueError("Unexpected end of expression")

        token = self.tokens[self.pos]
        op_type = token[1]

        if op_type == 'NUM':
            val = token[0]
            self.pos += 1
            return val

        elif op_type in ('+', '-'):
            raise ValueError(f"Unexpected operator: {token[0]}")

        elif op_type in ('*', '/'):
            raise ValueError(f"Unexpected operator: {token[0]}")

        elif op_type == 'OPEN_PAREN':
            self.pos += 1  # skip '('
            result = self.parse_expression()
            if not tokens or self.tokens[self.pos][1] != 'CLOSE_PAREN':
                raise ValueError("Mismatched parentheses")
            self.pos += 1  # skip ')'
            return result

        else:
            raise ValueError(f"Unexpected token type: {op_type}")

    def parse_expression(self):
        result = self.parse_term()
        while len(self.tokens) > self.pos:
            tok = self.tokens[self.pos]
            op = tok[1]
            if op == '+':
                self.pos += 1
                right = self.parse_term()
                result = result + right
            elif op == '-':
                self.pos += 1
                right = self.parse_term()
                result = result - right
            else:
                break
        return result

    def parse_term(self):
        result = self.parse_primary()
        while len(self.tokens) > self.pos:
            tok = self.tokens[self.pos]
            op = tok[1]
            if op == '*':
                self.pos += 1
                right = self.parse_primary()
                result = result * right
            elif op == '/':
                self.pos += 1
                right = self.parse_primary()
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                result = result / right
            else:
                break
        return result


def eval_expression(expr):
    """
    Evaluate a mathematical expression string following standard order of operations.

    Supports:
      - Parentheses for grouping
      - Operators: +, -, *, /
      - Negative numbers (unary minus)
      - Raises ZeroDivisionError on division by zero

    Examples:
      eval_expression("3 + 4 * (2 - 1)") -> 7
      eval_expression("-5 + 3") -> -2
      eval_expression("8 / 4 * (2 + 1)") -> 6
    """
    if not isinstance(expr, str):
        raise TypeError("Expression must be a string.")

    expr = expr.strip()
    if not expr:
        return None

    parser = ExpressionEvaluator()
    parser.tokens = []
    pos_attr = [0]

    def tokenize():
        tokens = []
        i = 0
        n = len(expr)
        while i < n:
            ch = expr[i]
            if ch.isdigit():
                j = i + 1
                while j < n and expr[j].isdigit():
                    j += 1
                num = int(expr[i:j])
                tokens.append((num, 'NUM'))
                pos_attr[0] = j
                i = j
            elif ch == '+':
                if not tokens:
                    # Unary plus at start (not standard)
                    raise ValueError(f"Unexpected '+'")
                prev_op = tokens[-1][1]
                tokens.append((ch, 'OPERATOR'))
                pos_attr[0] = i + 1
                i += 1
            elif ch == '-':
                if not tokens or tokens[-1][1] in ('NUM', ')'):
                    # Unary minus
                    j = i + 1
                    while j < n and expr[j].isdigit():
                        j += 1
                    num = int('-' + expr[i:j])
                    tokens.append((num, 'NUM'))
                    pos_attr[0] = j
                else:
                    tokens.append((ch, 'OPERATOR'))
                    pos_attr[0] = i + 1
                i += 1
            elif ch == '*':
                tokens.append((ch, 'OPERATOR'))
                pos_attr[0] = i + 1
                i += 1
            elif ch == '/':
                tokens.append((ch, 'OPERATOR'))
                pos_attr[0] = i + 1
                i += 1
            elif ch == '(':
                tokens.append(('(', 'PAREN_OPEN'))
                pos_attr[0] = i + 1
                i += 1
            elif ch == ')':
                tokens.append((')', 'PAREN_CLOSE'))
                pos_attr[0] = i + 1
                i += 1
            else:
                raise ValueError(f"Invalid character: {ch}")
        return tokens

    def parse():
        if not tokens or pos_attr[0] >= len(tokens):
            raise ValueError("Empty expression")
        value, type_token = tokens[pos_attr[0]]
        if type_token == 'NUM':
            pos_attr[0] += 1
            left = value
        elif type_token == 'PAREN_OPEN':
            pos_attr[0] += 1
            right_expr = parse()
            if pos_attr[0] >= len(tokens) or tokens[pos_attr[0]] != (')', 'PAREN_CLOSE'):
                raise ValueError("Mismatched parentheses")
            pos_attr[0] += 1
            return right_expr
        elif type_token == 'OPERATOR':
            raise ValueError(f"Unexpected operator: {tokens[pos_attr[0]-1]}")
        else:
            raise ValueError(f"Unexpected token type: {type_token}")

        while pos_attr[0] < len(tokens):
            op = tokens[pos_attr[0]][1]
            if op == '+':
                pos_attr[0] += 1
                right_val, _ = parse()
                left = left + right_val
            elif op == '-':
                pos_attr[0] += 1
                right_val, _ = parse()
                left = left - right_val
            elif op == '*':
                pos_attr[0] += 1
                right_val, _ = parse()
                left = left * right_val
            elif op == '/':
                pos_attr[0] += 1
                right_val, _ = parse()
                if right_val == 0:
                    raise ZeroDivisionError("division by zero")
                left = left / right_val
            else:
                break

        return left

    try:
        tokens = tokenize()
        result = parse()
        return result
    except Exception as e:
        if isinstance(e, ZeroDivisionError):
            raise
        raise ValueError(f"Invalid expression: {expr}") from e
